<script setup lang="ts">
import { computed, onBeforeUnmount, watch } from 'vue'
import { businessAllowedLabel, businessDecisionLabel, businessDiffLines, businessRequiredLabel, businessRoleLabel, businessSectionLabel, createBusinessController, type BusinessEditor } from './business-view'
import { formatPorts, missingDependencies } from './workspace-state'
import { errorText, formatTime, scopeLabel, useWorkspace } from './workspace'

const props = defineProps<{ conversationId: string; disabled?: boolean }>()
const emit = defineEmits<{ state: [value: { pending: boolean; busy: boolean }] }>()
const workspace = useWorkspace()
const controller = createBusinessController(workspace, () => props.conversationId, errorText, workspace.drafts.get('conversation-business-editors') as Map<string, BusinessEditor> | undefined)
workspace.drafts.set('conversation-business-editors', controller.editors)
const state = controller.editor
const editable = computed(() => !!state.value.context?.draft && ['draft', 'previewed'].includes(state.value.context.draft.status))
const blocked = computed(() => !!props.disabled || state.value.busy || !!state.value.mutation.pendingBody)
const dependencies = computed(() => missingDependencies(state.value.selected, state.value.context?.preview?.section_dependencies))
const latestBusiness = computed(() => { const value = state.value.mutation.result?.business; return value?.target?.ref === state.value.context?.target.ref ? value : null })
const refreshKey = computed(() => `${props.conversationId}/${workspace.unlocked.value}/${workspace.currentIntent.value?.revision ?? ''}/${workspace.messages.value.length}/${workspace.jobs.value.filter(job => job.conversation_id === props.conversationId).map(job => `${job.id}:${job.view_seq}`).join(',')}`)
watch(refreshKey, () => { void controller.load() }, { immediate: true })
watch(() => [!!state.value.mutation.pendingBody, state.value.busy, props.conversationId] as const, () => emit('state', { pending: !!state.value.mutation.pendingBody, busy: state.value.busy }), { immediate: true })
onBeforeUnmount(() => { controller.dispose(); emit('state', { pending: false, busy: false }) })
</script>

<template>
  <section v-if="conversationId" class="conversation-business" aria-labelledby="conversation-business-heading">
    <header><div><h2 id="conversation-business-heading">业务资料</h2><p>对话与表单共用草稿，确认前核对每一部分。</p></div><button type="button" class="text-action" :disabled="state.loading || state.busy" @click="controller.load">重新读取</button></header>
    <p v-if="state.loading && !state.context" class="business-note" role="status">正在读取当前会话已保存的业务对象。</p>
    <p v-if="state.busy" class="business-note" role="status">正在保存本次业务动作，请保留当前提交。</p>
    <template v-if="state.context">
      <p class="business-target">{{ scopeLabel(state.context.target.scope.boundary, state.context.target.scope.direction) }}<span>{{ state.context.target.asset_ids.length }} 个明确对象</span><span v-if="state.context.draft">草稿修订 {{ state.context.draft.revision }}</span></p>
      <details class="business-objects"><summary>核对对象与资料</summary><ul><li v-for="asset in state.context.target.asset_ids" :key="asset">{{ asset }}</li></ul><p>固定资料 {{ state.context.target.snapshot_id }}</p></details>
      <div v-if="state.context.draft" class="business-draft">
        <p class="business-note">{{ state.context.draft.status === 'confirmed' ? '本稿已明确确认。后续修改会保留原版本。' : state.context.draft.status === 'rejected' ? '本稿已拒绝，原始事实与旧确认保留。' : '草稿内容尚未成为新的业务判据。角色、必要访问与允许范围分别声明。' }}</p>
        <details v-for="change in state.context.draft.changes" :key="change.asset_id" class="business-asset" :open="state.context.draft.changes.length === 1"><summary>{{ change.asset_id }}</summary><p class="business-declaration"><strong>资产允许上界</strong>{{ businessAllowedLabel(change.access) }}</p><article v-for="role in change.roles" :key="role.service_id" class="business-service"><h3>{{ businessRoleLabel(role.role) }} <small>{{ role.declared === false ? '沿用原声明' : '本次待核对' }}</small></h3><p>{{ role.protocol.toUpperCase() }} {{ formatPorts(role.ports) || '端口待明确' }}</p><dl><dt>允许范围</dt><dd>{{ businessAllowedLabel(change.access?.services.find(service => service.service_id === role.service_id)) }}</dd><dt>必要访问</dt><dd>{{ businessRequiredLabel(change.access?.services.find(service => service.service_id === role.service_id)) }}</dd></dl></article><details v-if="change.access?.exceptions?.length"><summary>业务例外（{{ change.access.exceptions.length }}）</summary><article v-for="(exception, index) in change.access.exceptions" :key="index" class="business-exception"><strong>{{ exception.check_id }}{{ exception.subcheck ? ` / ${exception.subcheck}` : '' }}</strong><p>{{ exception.reason || '理由待补' }}</p><p>授权来源：{{ exception.authorization_source || '尚未声明，新的例外不能确认' }}</p><p>到期：{{ formatTime(exception.expires_at) }}</p></article></details></details>
        <div class="business-actions"><RouterLink :to="{ path: '/inventory', query: { draft: state.context.draft.id } }">在同一表单中编辑</RouterLink><button v-if="editable" type="button" :disabled="blocked" @click="controller.submit({ action: 'preview' })">重新预览差异</button></div>
      </div>
      <div v-else class="business-empty"><p>已有资料会自动带入。可在对话中明确服务用途、允许来源或必要访问，也可以保留未知。</p><button type="button" :disabled="blocked" @click="controller.submit({ action: 'preview' })">打开共用业务草稿</button></div>
      <section v-if="state.context.candidates.length" class="business-candidates" aria-label="角色候选与证据"><h3>待人工核对的用途</h3><article v-for="candidate in state.context.candidates" :key="candidate.ref" class="business-candidate"><header><strong>{{ businessRoleLabel(candidate.role) }}</strong><span>{{ businessDecisionLabel(candidate.decision) }}</span></header><p>{{ candidate.asset_id }}{{ candidate.service_id ? ` / ${candidate.service_id}` : '' }}</p><p v-if="candidate.conflicts_with_confirmed" class="business-warning">与已有确认不同。旧版会保留，须核对差异后明确确认新版本。</p><details><summary>支持证据 {{ candidate.evidence.length }} 项；反向证据 {{ candidate.contradicting_evidence.length }} 项</summary><ul><li v-for="(item, index) in candidate.evidence" :key="`support-${index}`">支持：{{ item.document === 'input' ? '固定资料' : '规则证据' }} {{ item.field }}</li><li v-for="(item, index) in candidate.contradicting_evidence" :key="`against-${index}`">反向：{{ item.document === 'input' ? '固定资料' : '规则证据' }} {{ item.field }}</li><li v-for="item in candidate.unknowns" :key="item">待核实：{{ item }}</li><li v-for="item in candidate.questions" :key="item">需确认：{{ item }}</li></ul></details><div class="business-actions"><button type="button" :disabled="blocked" @click="controller.submit({ action: 'accept_candidate', candidate_ref: candidate.ref })">加入草稿并预览</button><button type="button" :disabled="blocked" @click="controller.submit({ action: 'reject_candidate', candidate_ref: candidate.ref })">拒绝候选</button><button type="button" :disabled="blocked" @click="controller.submit({ action: 'keep_unknown', candidate_ref: candidate.ref, unknown_fields: ['role'] })">保留未知</button></div></article></section>
      <section v-if="state.context.preview" class="business-preview" aria-label="业务确认差异"><h3>确认前的差异</h3><p>仅保存你勾选的部分，不修改云端配置。</p><details v-for="(diff, index) in state.context.preview.diff" :key="index" class="business-diff"><summary>{{ diff.asset_id }} / {{ businessSectionLabel(diff.section) }}</summary><div><strong>原版本</strong><ul><li v-for="(line, lineIndex) in businessDiffLines(diff.before, diff.section)" :key="lineIndex">{{ line }}</li></ul></div><div><strong>待确认</strong><ul><li v-for="(line, lineIndex) in businessDiffLines(diff.after, diff.section)" :key="lineIndex">{{ line }}</li></ul></div></details><p v-if="state.context.preview.validation_errors?.length" class="business-warning">部分业务项目仍缺少有效确认条件，已保留在草稿。请补齐相应来源、范围或例外授权后再预览。</p><fieldset :disabled="blocked"><legend>明确选择本次确认部分</legend><label v-for="section in state.context.preview.confirmable_sections" :key="section"><input v-model="state.selected" type="checkbox" :value="section" />{{ businessSectionLabel(section) }}</label></fieldset><p v-if="dependencies.length" class="business-warning">所选部分还依赖{{ dependencies.map(businessSectionLabel).join('、') }}，请分别核对并明确勾选；系统不会自动选择。</p><button type="button" class="business-confirm" :disabled="blocked || !state.selected.length || !!dependencies.length" @click="controller.confirm">确认勾选的部分</button></section>
      <p v-if="latestBusiness?.unknown_fields.length" class="business-note">未知项仍保留，不据此推断允许范围或业务授权。</p>
    </template>
    <p v-else-if="!state.loading && !state.error" class="business-note">当前目标尚无可绑定的已封存资产资料。可继续对话明确对象，资料就绪后再补业务要求。</p>
    <p v-if="state.error" class="business-warning" role="alert">{{ state.error }}</p><p v-if="state.message" class="business-note" role="status">{{ state.message }}</p>
    <div v-if="state.mutation.pendingBody && !state.busy" class="business-pending"><p>本次业务保存结果尚需核对。原对象、内容和提交标识已保留。</p><button type="button" :disabled="state.busy || disabled" @click="controller.submit()">以原内容核对这次提交</button><button type="button" :disabled="state.loading" @click="controller.load">先读取服务端草稿</button></div>
    <p v-if="state.context" class="business-footnote">用途与端口线索不证明实际监听、可达性或访问授权。表单修改后，请重新读取并预览。</p>
  </section>
</template>

<style scoped>
.conversation-business{min-width:0;margin:20px 0 0;padding:18px 0;border-top:1px solid #dce6e1;font-size:12px;line-height:1.75}.conversation-business>header,.business-candidate>header{display:flex;align-items:start;justify-content:space-between;gap:12px}.conversation-business h2{font-size:16px;margin:0}.conversation-business h3{font-size:13px;margin:0 0 7px}.conversation-business p{margin:5px 0 10px;overflow-wrap:anywhere}.conversation-business header p,.business-note,.business-footnote,.business-objects{color:#64748b;font-size:11px}.business-target{display:flex;flex-wrap:wrap;gap:4px 14px;color:#334155}.business-objects>p{font-size:10px}.conversation-business summary{cursor:pointer;overflow-wrap:anywhere}.conversation-business ul{margin:7px 0;padding-left:18px}.conversation-business button{padding:0;border:0;background:none;color:#047857;text-align:left;font-size:11px;line-height:1.7}.conversation-business button:disabled{color:#94a3b8;cursor:default}.business-asset{margin-top:14px;padding-top:10px;border-top:1px solid #e2e8f0}.business-asset>summary{font-weight:600}.business-service{padding:11px 0;border-bottom:1px solid #edf2ef}.business-service h3 small{font-size:10px;font-weight:400;color:#64748b;margin-left:8px}.business-service dl{display:grid;grid-template-columns:56px minmax(0,1fr);gap:7px 10px;margin:10px 0 0}.business-service dt{color:#64748b}.business-service dd{margin:0;overflow-wrap:anywhere}.business-declaration strong{display:block;margin-top:9px;font-size:11px;font-weight:500}.business-actions{display:flex;flex-wrap:wrap;gap:8px 14px;margin:11px 0}.business-actions a{font-size:11px}.business-candidates,.business-preview{margin-top:18px;padding-top:15px;border-top:1px solid #dce6e1}.business-candidate{padding:12px 0;border-bottom:1px solid #e2e8f0}.business-candidate header span{font-size:10px;color:#64748b}.business-candidate>p{font-size:10px}.business-diff{margin:12px 0;padding:9px 12px;background:#f8fbf9;border-left:2px solid #bdd5c8}.business-diff>div{margin-top:8px;font-size:11px}.business-diff strong{font-weight:500;color:#526c60}.business-preview fieldset{padding:0!important;border:0!important;margin:16px 0 10px!important}.business-preview legend{font-size:11px;color:#64748b;margin-bottom:8px}.business-preview fieldset label{display:flex;align-items:center;gap:7px;font-size:12px!important;margin:8px 0}.business-preview input[type=checkbox]{width:14px;height:14px;accent-color:#047857}.conversation-business .business-confirm{padding:8px 12px;color:white;background:#047857;border-radius:5px}.conversation-business .business-confirm:disabled{background:#e2e8f0;color:#64748b}.business-warning{font-size:11px;color:#92400e}.business-pending{margin-top:14px;padding:10px 12px;background:#fff7e7;color:#7d5513}.business-pending button+button{margin-left:14px}.business-footnote{margin-top:17px!important;border-top:1px solid #edf2ef;padding-top:12px}.business-exception{margin-top:9px;font-size:11px}.conversation-business button:focus-visible,.conversation-business a:focus-visible,.conversation-business summary:focus-visible{outline:3px solid #2563eb;outline-offset:3px}@media(max-width:600px){.business-service dl{grid-template-columns:1fr;gap:2px}.business-service dd{margin-bottom:8px}.business-actions{gap:9px 16px}.conversation-business{font-size:12px}.business-target{display:block}.business-target span{display:block;font-size:11px}}
</style>
